// ─── Fuentes RSS ──────────────────────────────────────────────────────────
// Edita esta lista con los medios que quieras seguir. `scope` alimenta el
// filtro Colombia / Internacional del panel.
//
// ⚠ Las URL cambian con el tiempo y algunos medios retiran sus feeds. Si una
// deja de responder, el panel sigue funcionando con las demás y avisa de cuál
// ha fallado.
const FEEDS = [
  { url: 'https://www.elespectador.com/arc/outboundfeeds/rss/', source: 'El Espectador', scope: 'co' },
  { url: 'https://www.eltiempo.com/rss/tecnosfera.xml',         source: 'El Tiempo',      scope: 'co' },
  { url: 'https://www.larepublica.co/rss/empresas',             source: 'La República',   scope: 'co' },
  { url: 'https://www.portafolio.co/rss/negocios',              source: 'Portafolio',     scope: 'co' },
  { url: 'https://techcrunch.com/feed/',                        source: 'TechCrunch',     scope: 'intl' },
  { url: 'https://www.theverge.com/rss/index.xml',              source: 'The Verge',      scope: 'intl' },
  { url: 'https://www.socialmediatoday.com/feeds/news/',        source: 'Social Media Today', scope: 'intl' },
  { url: 'https://searchengineland.com/feed',                   source: 'Search Engine Land', scope: 'intl' },
];

// Un RSS no trae tema ni relevancia: se deducen del titular. Es una heurística,
// y el panel la presenta como clasificación automática, no como dato del medio.
const TOPICS = {
  Algoritmo:  ['algoritmo', 'alcance', 'feed', 'ranking', 'posicionamiento'],
  Plataformas:['instagram', 'tiktok', 'youtube', 'linkedin', 'meta', 'reels', 'shorts', 'threads'],
  Ventas:     ['ventas', 'prospección', 'leads', 'clientes', 'conversión', 'embudo'],
  Formatos:   ['vídeo', 'video', 'carrusel', 'pódcast', 'podcast', 'newsletter', 'directo'],
  Regulación: ['regulación', 'ley', 'sic', 'privacidad', 'datos personales', 'multa'],
  IA:         ['inteligencia artificial', ' ia ', 'openai', 'modelo', 'automatiza'],
  Negocio:    ['inversión', 'facturación', 'mercado', 'agencia', 'presupuesto', 'crecimiento'],
};

// Cuantas más de estas aparezcan, más arriba sale la noticia.
const INTERES = ['instagram', 'linkedin', 'youtube', 'tiktok', 'reels', 'shorts',
                 'creador', 'contenido', 'b2b', 'agencia', 'alcance', 'engagement',
                 'algoritmo', 'marca', 'redes sociales', 'publicación', 'formato'];

const LIMIT = Math.min(Number($input.first().json.query?.limit ?? 12), 40);

return FEEDS.map((feed) => ({ json: { ...feed, limit: LIMIT, topics: TOPICS, interes: INTERES } }));

// El nodo XML descarta el elemento cuando el cuerpo no es XML válido, y al
// desaparecer del flujo desplaza a los siguientes: los artículos acabarían
// firmados por el medio equivocado. Aquí se sustituye cualquier respuesta no
// válida por un feed vacío, de modo que entran y salen tantos elementos como
// fuentes y la posición sigue siendo de fiar.
const VACIO = '<?xml version="1.0"?><rss version="2.0"><channel></channel></rss>';

return $input.all().map((item, i) => {
  const body = typeof item.json?.data === 'string' ? item.json.data : '';
  const valido = /<(rss|feed)[\s>]/i.test(body);
  return { json: { data: valido ? body : VACIO, indice: i, respondio: valido } };
});

// Une lo devuelto por cada feed, lo normaliza y lo ordena.
//
// El emparejamiento NO puede ir por índice: un feed caído no produce salida y
// desplaza todo lo que viene detrás, con lo que los artículos acabarían
// firmados por el medio equivocado. Se usa pairedItem, que n8n mantiene aunque
// falten elementos, y el dominio como red de seguridad.
const feeds = $('Fuentes').all().map((i) => i.json);
const estado = $('Sanear respuestas').all().map((i) => i.json);
const parsed = $input.all();

const vistos = new Set();
const items = [];

function textOf(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  return v._ ?? v['#text'] ?? '';
}

parsed.forEach((entry, position) => {
  const feed = feeds[position];
  if (!feed) return;
  if (estado[position]?.respondio) vistos.add(feed.source);
  const body = entry.json ?? {};
  const raw = body.rss?.channel?.item ?? body.feed?.entry ?? null;
  if (!raw) return;

  for (const article of [].concat(raw)) {
    const title = textOf(article.title).trim();
    if (!title) continue;

    const link = textOf(article.link) || article.link?.$?.href || article.guid?._ || '';
    const when = textOf(article.pubDate) || textOf(article.published) || textOf(article.updated);
    const html = textOf(article.description) || textOf(article['content:encoded']) || textOf(article.summary);

    const summary = html.replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/gi, ' ')
      .replace(/\s+/g, ' ').trim().slice(0, 240);

    const cover = article.enclosure?.$?.url
      ?? article['media:content']?.$?.url
      ?? article['media:thumbnail']?.$?.url
      ?? (html.match(/<img[^>]+src=["']([^"']+)["']/i) ?? [])[1]
      ?? null;

    const haystack = (title + ' ' + summary).toLowerCase();
    const topic = Object.entries(feed.topics)
      .find(([, words]) => words.some((w) => haystack.includes(w)))?.[0] ?? 'Negocio';

    const published = when ? new Date(when) : null;
    const minutes = published && !Number.isNaN(published.getTime())
      ? Math.max(1, Math.round((Date.now() - published.getTime()) / 60000))
      : null;

    // Puntúa por cercanía al tema y por frescura: una noticia de hoy sobre tu
    // plataforma pesa más que una de ayer sobre el sector en general.
    const hits = feed.interes.filter((w) => haystack.includes(w)).length;
    const score = hits + (minutes != null && minutes < 180 ? 2 : minutes != null && minutes < 720 ? 1 : 0);
    const relevance = score >= 3 ? 'alta' : score >= 2 ? 'media' : 'baja';

    items.push({
      id: link || `${feed.source}-${title.slice(0, 40)}`,
      source: feed.source,
      scope: feed.scope,
      title: title.slice(0, 160),
      summary: summary || null,
      cover,
      link: link || null,
      topic,
      relevance,
      minutes,
      score,
    });
  }
});

// Un feed sin salida es un feed que no respondió.
const fallos = feeds.map((f) => f.source).filter((s) => !vistos.has(s));

const orden = { alta: 0, media: 1, baja: 2 };
items.sort((a, b) => (orden[a.relevance] - orden[b.relevance]) || ((a.minutes ?? 1e9) - (b.minutes ?? 1e9)));

return [{ json: {
  source: 'rss',
  errors: fallos.length ? [`Sin respuesta: ${fallos.join(', ')}`] : [],
  items: items.slice(0, feeds[0]?.limit ?? 12),
} }];
